"""Four more independent test solutions."""
import json
from pathlib import Path
ANSWERS=[
('1998/A','Output symmetric pairs (xc-d,yc) and (xc+d,yc) for d=1..k/2. If k is odd also output the center itself. All points are distinct and symmetric pairs average to the center. Coordinates stay within 600 of the input center. O(k) time, O(1) extra space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){int t;cin>>t;while(t--){int x,y,k;cin>>x>>y>>k;if(k%2)cout<<x<<' '<<y<<'\n';for(int d=1;d<=k/2;d++)cout<<x-d<<' '<<y<<'\n'<<x+d<<' '<<y<<'\n';}}'''),
('1998/B','Set q[i]=p[i]%n+1. Every subarray not containing the original n gains its length in sum. A subarray containing n instead gains length-n. Thus equality occurs only for the whole array, which is unavoidable for two permutations. This attains the lower bound one, including n=1. O(n) time, O(1) auxiliary space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;for(int i=0,x;i<n;i++){cin>>x;cout<<x%n+1<<(i+1==n?'\n':' ');}}}'''),
('1998/C','Separate the distinguished removed element by b. If b=1, transfer all spent increments to it: reducing the remaining median by at most the transferred amount cannot reduce the score. Hence try every eligible element plus k and its original exclusion median, using sorted positions. For b=0 it suffices to choose the largest immutable element: exchanging a smaller distinguished immutable element with a larger one can reduce the remaining median by at most their difference. Binary-search the largest attainable median after excluding that element. To make the lower median at least X requires ceil(n/2) of the remaining elements to be >=X; count existing large elements and upgrade the largest eligible smaller ones first. O(n log n+n log(max(a)+k)) time, O(n) space.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;ll k;cin>>n>>k;vector<ll>a(n);vector<int>b(n);for(auto&x:a)cin>>x;for(int&x:b)cin>>x;vector<pair<ll,int>>v;for(int i=0;i<n;i++)v.push_back({a[i],b[i]});sort(v.begin(),v.end());ll ans=0;int immutable=-1,rank=(n-2)/2;for(int i=0;i<n;i++){int medpos=rank+(i<=rank);ans=max(ans,v[i].first+v[medpos].first);if(v[i].second)ans=max(ans,v[i].first+k+v[medpos].first);else immutable=i;}if(immutable!=-1){auto good=[&](ll x){int need=(n+1)/2;for(int i=0;i<n;i++)if(i!=immutable&&v[i].first>=x)--need;if(need<=0)return true;ll cost=0;for(int i=n-1;i>=0&&need;i--)if(i!=immutable&&v[i].second&&v[i].first<x){cost+=x-v[i].first;if(cost>k)return false;--need;}return need==0;};ll lo=0,hi=v.back().first+k;while(lo<hi){ll mid=(lo+hi+1)/2;if(good(mid))lo=mid;else hi=mid-1;}ans=max(ans,v[immutable].first+lo);}cout<<ans<<'\n';}}'''),
('1998/D','Compute shortest Elsie distances d[u] in increasing vertex order. An alternative edge u->v can first jump strictly ahead of Bessie for starts s in [u+1,v-d[u]-2]. Bessie has made d[u]+1 moves when Elsie takes this jump; landing at her position loses because Bessie moves next. Starting to the right of u keeps Bessie ahead until some overtake; if a shortest path already overtakes earlier, that earlier edge already proves loss. Conversely the first overtake must use such an edge, and starts <=u cannot be first overtaken there. Union these intervals using a difference array. All starts not covered win. O(n+m) time and space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,m;cin>>n>>m;vector<vector<int>>g(n+1);for(int i=0,u,v;i<m;i++){cin>>u>>v;g[u].push_back(v);}vector<int>d(n+1,n+1),delta(n+3);d[1]=0;for(int u=1;u<=n;u++){if(u<n)d[u+1]=min(d[u+1],d[u]+1);for(int v:g[u]){d[v]=min(d[v],d[u]+1);int l=u+1,r=v-d[u]-2;if(l<=r){delta[l]++;delta[r+1]--;}}}int active=0;for(int s=1;s<n;s++){active+=delta[s];cout<<(active?'0':'1');}cout<<'\n';}}''')]
if __name__=='__main__':
    p=Path('backend/data/bench/codeforces700_20261116/assistant_answers_v1/shard_test_000_199.jsonl')
    with p.open('a',encoding='utf-8') as out:
        for ident,explanation,code in ANSWERS:
            out.write(json.dumps({'id':ident,'split':'test','author':'current chat assistant','status':'authored','explanation':explanation,'cpp_code':code,'validation':'not executed'})+'\n')
